"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def BubbleSortWords(words):
    n = len(words)
    for i in range(0, n):
        for j in range(0, n - i - 1):
            if (words[j] > words[(j + 1)]):
                temp_var = words[j]
                words[j] = words[(j + 1)]
                words[(j + 1)] = temp_var
    return words
